INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('80e3267b-a4e6-5419-9ead-279ea64b9ca3', '4c336d6a-47cc-560c-a6e5-944ee3a0d74a', 'en', $h$Pneumatic Grease Pump Drum Type 45:1 – 2450$h$, $h$pneumatic-grease-pump-drum-type-451-2450$h$, NULL, $h$<div> <div><p><strong>Why the 2450 Pneumatic Grease Pump?</strong></p><p>This drum-type pneumatic grease pump has a 45:1 pressure ratio. It mounts easily onto standard 185 kg grease drums with the help of a drum cover. It is ideal for short-distance, high-pressure lubrication. No hose is supplied with the pump. The piston diameter is Ø62 mm. Use the follower plate and its weight. This equipment compacts the grease inside the drum. It makes pump feed easier with high-viscosity greases and in cold regions. The operating pressure ranges between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. Optional accessories enhance its functionality. With these models, you select the accessories your system needs separately.</p></div> </div>$h$, NULL, $h$Pneumatic Grease Pump Drum Type 45:1 – 2450 | HD Marine$h$, $h$Why the 2450 Pneumatic Grease Pump? This drum-type pneumatic grease pump has a 45:1 pressure ratio. It mounts easily onto standard 185 kg grease drums…$h$, 'auto') ON CONFLICT DO NOTHING;
