INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('d902177b-de5e-5a43-9205-8fabe4034e8c', '4a404165-69dc-5f7b-a884-9ea8cc11b788', 'en', $h$Pneumatic Grease Pump 50 Kg – 2250$h$, $h$pneumatic-grease-pump-50-kg-2250$h$, NULL, $h$<div> <div><p><strong>Why the 2250 Pneumatic Grease Pump?</strong></p><p>This air-operated grease pump with a 70:1 pressure ratio offers a 50 kg grease capacity. It is ideal for long-distance, high-pressure lubrication. Four swivel casters let you steer it easily. The pump uses a steel-wire-reinforced hydraulic hose. The piston diameter is Ø75 mm. The follower plate and spring compact the grease inside the reservoir. This feature makes pump feed easier with high-viscosity greases and in cold regions. In addition, the Z swivel joint at the grease gun inlet lets you handle the hose and gun more easily. The operating pressure ranges between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. Optional accessories enhance its functionality.</p></div> </div>$h$, NULL, $h$Pneumatic Grease Pump 50 Kg – 2250 | HD Marine$h$, $h$Why the 2250 Pneumatic Grease Pump? This air-operated grease pump with a 70:1 pressure ratio offers a 50 kg grease capacity. It is ideal for…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('066a8041-c925-59e7-ac52-efd9c2848f1a', '11292086-8ed7-50cc-b495-ad8980827948', 'en', $h$Pneumatic Grease Pump 30 Kg – 2230$h$, $h$pneumatic-grease-pump-30-kg-2230$h$, NULL, $h$<div> <div><p><strong>Why the 2230 Pneumatic Grease Pump?</strong></p><p>This air-operated grease pump offers a 30 kg grease capacity with a 70:1 pressure ratio. We designed it as an ideal solution for your long-distance, high-pressure lubrication jobs. Thanks to its four swivel casters, you can steer the pump easily. We use a steel-wire-reinforced hydraulic hose in the pump, and the piston diameter is Ø75 mm. The follower plate and spring compact the grease inside the reservoir; this way, you can easily keep the pump fed with high-viscosity greases and in cold regions. The Z swivel joint at the grease gun inlet lets you use the hose and gun more comfortably. The pump runs at an operating pressure between a minimum of 6 bar and a maximum of 8 bar. We strongly recommend using filtered and lubricated air to maximize the pump's performance and service life. Optional accessories enhance the product's functionality.</p></div> </div>$h$, NULL, $h$Pneumatic Grease Pump 30 Kg – 2230 | HD Marine$h$, $h$Why the 2230 Pneumatic Grease Pump? This air-operated grease pump offers a 30 kg grease capacity with a 70:1 pressure ratio. We designed it as an ideal…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('6c59a0b2-6601-5a1f-b8f1-93796a64bf17', '91796af3-d0c6-5856-bbe2-5e1029fbe4b3', 'en', $h$Pneumatic Grease Pump 16 Kg – 2226$h$, $h$pneumatic-grease-pump-16-kg-2226$h$, NULL, $h$<div> <div><p><strong>Why the 2226 Pneumatic Grease Pump?</strong></p><p>This air-operated grease pump with a 70:1 pressure ratio mounts easily onto standard 16 kg grease pails and is carried around with ease. It is ideal for long-distance, high-pressure lubrication. The pump uses a steel-wire-reinforced hydraulic hose. The piston diameter is Ø75 mm. The follower plate and spring compact the grease inside the pail. This feature makes pump feed easier with high-viscosity greases and in cold regions. In addition, the Z swivel joint at the grease gun inlet lets you handle the hose and gun more easily. The operating pressure ranges between a minimum of 6 bar and a maximum of 8 bar. Use filtered and lubricated air to increase the pump's performance and service life. Optional accessories enhance its functionality. The product is shipped without the pail.</p></div> </div>$h$, NULL, $h$Pneumatic Grease Pump 16 Kg – 2226 | HD Marine$h$, $h$Why the 2226 Pneumatic Grease Pump? This air-operated grease pump with a 70:1 pressure ratio mounts easily onto standard 16 kg grease pails and is carried…$h$, 'auto') ON CONFLICT DO NOTHING;
INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('de610dbd-a8b2-509d-a921-9d0c5d476d06', '1e4f2efe-34c5-5f22-81cd-5b9ce02b08de', 'en', $h$Mechanical Grease Pump 20 Kg – 2025$h$, $h$mechanical-grease-pump-20-kg-2025$h$, NULL, $h$<div> <div><p><strong>Why the 2025 Mechanical Grease Pump?</strong></p><p>This grease pump with a 20 kg capacity operates mechanically. The pump uses a steel-wire-reinforced hydraulic hose. It is ideal for short-distance, high-pressure lubrication. Thanks to the follower plate and spring, the grease inside the reservoir is compacted, making pump feed easy with high-viscosity greases and in cold regions. It has two fixed wheels and, being lightweight, is carried around easily; the foot pedal also keeps the pump steady during operation. It offers users an alternative in locations without a compressed air system.</p></div> </div>$h$, NULL, $h$Mechanical Grease Pump 20 Kg – 2025 | HD Marine$h$, $h$Why the 2025 Mechanical Grease Pump? This grease pump with a 20 kg capacity operates mechanically. The pump uses a steel-wire-reinforced hydraulic hose…$h$, 'auto') ON CONFLICT DO NOTHING;
