INSERT INTO product_translations (id, product_id, locale, name, slug, summary, description, usage_areas, meta_title, meta_description, translation_status) VALUES ('43132839-a5be-55fd-982b-6fc1a27c7b8f', 'f1d01aa6-5a85-55fe-9bd5-fc730f238668', 'en', $h$Mechanical Oil Pump 80 Lt – 4004$h$, $h$mechanical-oil-pump-80-lt-4004$h$, NULL, $h$<div> <div><p><strong>Why the 4004 Mechanical Oil Pump?</strong></p><p>The Model 4004 mechanical oil filling pump has an 80 Lt capacity and operates mechanically. It has two swivel and two fixed wheels. The funnel on top of the tank allows the tank to be filled easily, and the carrying handle makes the pump easy to move around. It is an alternative for users in locations without a compressed air system.</p></div> </div>$h$, NULL, $h$Mechanical Oil Pump 80 Lt – 4004 | HD Marine$h$, $h$Why the 4004 Mechanical Oil Pump? The Model 4004 mechanical oil filling pump has an 80 Lt capacity and operates mechanically. It has two swivel and two…$h$, 'auto') ON CONFLICT DO NOTHING;
